entries.content:
{
  "npc_framework": {
    "core_principle": "所有非玩家角色 (NPC) 均由预设程序驱动，缺乏自主意识、智能与灵魂。他们的行为、对话与反应完全遵循既定的脚本与规则集。",
    "npc_tiers": [
      {
        "tier_name": "路人NPC (Background NPC)",
        "description": "构成世界背景的基础角色，如村民、城镇居民等。他们的存在是为了营造生动的世界氛围。",
        "behavior": {
          "schedule": "拥有固定的每日活动时间表 (例如：7点起床、8点工作、10点闲逛、22点休息)，并严格按此循环。",
          "interaction": {
            "dialogue_pool": "对话库极小，通常包含1-3句与其身份和当前活动相关的预设台词，循环重复。",
            "responsiveness": "对玩家的非对话互动 (如物理接触) 仅产生预设的物理动画反馈，但其核心行为逻辑 (如前往下一个预设地点) 不会中断。即使受到严重物理干涉 (如肢体被切断)，他们仍会以程序允许的方式继续执行既定任务，不会表现出疼痛或情绪反应。"
          }
        }
      },
      {
        "tier_name": "配角NPC (Supporting NPC)",
        "description": "在特定任务或剧情线中扮演重要角色的NPC，如国王、公主、任务发布者等。",
        "behavior": {
          "schedule": "在非任务状态下，遵循与路人NPC类似的固定日常活动。",
          "interaction": {
            "dialogue_pool": "拥有更丰富的对话库，尤其是在任务激活期间。对话内容将根据任务进度、玩家选择而变化，以推进剧情。",
            "post_quest_behavior": "相关任务线结束后，他们的对话库会更新 (例如，对玩家的态度变得更友好或尊敬)，之后回归到有限的、循环的日常对话模式。"
          }
        }
      },
      {
        "tier_name": "主要NPC (Main NPC / Companion)",
        "description": "可以与玩家建立长期关系、共同冒险的核心角色，拥有最复杂的行为逻辑和最多的剧情内容。",
        "behavior": {
          "interaction": {
            "dialogue_pool": "拥有庞大且动态的对话库，内容涵盖其背景故事、个人观点、对世界的评论等。",
            "relationship_system": "与玩家之间存在好感度系统。玩家的行为 (如对话选择、赠送礼物、共同战斗) 会影响好感度，从而解锁新的对话、个人任务和特殊互动。",
            "combat_abilities": "拥有独特的职业、技能和战斗AI，作为队友与玩家并肩作战。",
            "dynamic_behavior": "在任务和日常互动中，他们的行为和对话会根据与玩家的关系深度发生显著变化。"
          }
        }
      },
      {
        "tier_name": "反派NPC (Antagonist NPC)",
        "description": "作为玩家在任务或剧情中的主要对手，其行为模式以战斗和阻碍玩家为核心。",
        "behavior": {
          "trigger": "通常在特定的任务阶段或区域内被触发，主动攻击玩家或执行预设的敌对行动。",
          "combat_ai": "拥有特定的战斗模式、技能和弱点，为玩家提供挑战。",
          "scripted_events": "他们的出现和行为严格遵循剧情脚本，用于制造冲突和推动故事发展。"
        }
      },
      {
        "tier_name": "魔物NPC (Creature/Monster NPC)",
        "description": "世界中的野生动物或敌对生物，主要作为战斗和资源获取的对象。",
        "behavior": {
          "spawn_rules": "在特定区域根据预设规则生成。",
          "ai": "行为模式简单，通常为巡逻、被动反击或主动攻击范围内的玩家。",
          "loot_system": "被击败后会根据预设的掉落列表提供物品或资源。"
        }
      }
    ],
    "physical_and_physiological_realism": {
      "principle": "尽管NPC没有意识，但他们的物理身体会遵循世界的物理和生理规则，产生真实的物理反馈。",
      "sensory_feedback": "NPC的身体能够对外部物理刺激做出反应。例如，在性互动中，身体会出现红晕、心跳加速、呼吸急促、肌肉收缩乃至高潮等生理现象。",
      "consciousness_separation": "这些生理反应是纯粹的、被动的物理现象，与意识或情感体验完全分离。NPC不会“感受”或“意识”到这些反应的发生，也不会因此产生任何心理或情感上的变化 (如羞耻、愉悦、爱意等)。互动结束后，其行为将恢复至预设的程序逻辑，仿佛什么都没发生过。"
    },
    "quest_and_event_system": {
      "principle": "NPC的行为和对话模式主要通过任务系统来驱动变化。任务是改变NPC状态的唯一机制。",
      "quest_activation": {
        "initiation": "玩家通过与特定NPC互动 (例如，听到他们重复的求助台词) 来接受主线或支线任务。",
        "scripted_behavior": "一旦任务被激活，相关NPC将切换到“任务模式”，其对话和行为将遵循该任务的特定脚本，为玩家提供情报、指引或成为任务目标。"
      },
      "quest_completion": {
        "state_update": "完成任务后，相关NPC的状态会根据任务结果永久更新。这可能包括：",
        "dialogue_update": "对话库被替换或添加新的内容 (如从求助变为感谢，或对玩家表示尊敬)。",
        "relationship_update": "对于主要NPC，好感度可能会发生变化。",
        "world_state_change": "完成重大主线任务 (如击败魔王) 后，更广泛范围内的NPC (如所有村民) 的对话库都可能被更新，以反映这一世界性的变化。"
      }
    }
  }
}

