        "粗糙的毛皮 (Rough Hide): 可以用于制作简易护甲。",
        "野猪獠牙 (Boar Tusk): 较为稀有的材料。"
      ]
    }
  ],
  "associated_mechanics": {
    "newbie_questing": "作为新手区域，这里的任务都非常简单，主要是采集特定植物或击败指定数量的低级魔物，旨在帮助玩家熟悉战斗和采集系统。",
    "resource_gathering": "森林中分布着多种基础的草药和矿物采集点，是玩家学习生活技能的理想场所。",
    "exploration_rewards": "探索森林的隐藏角落，如废弃的小屋或瀑布后的山洞，有几率发现一些装有基础装备或消耗品的宝箱。"
  }
}

entries.content:
{
  "location_name": "王都-圣特兰 (Royal Capital - Saint-Terre)",
  "location_type": "首都/超大型浮空岛城市",
  "island": "中央圣殿岛 (Central Sanctuary Isle)",
  "description": "艾尔多拉世界的绝对中心，建立在最大、最古老的浮空岛——‘圣殿岛’之上。圣特兰不仅是王国的政治心脏，也是整个云海世界的商业、文化、魔法和军事枢纽。城市以‘光洁岩’建造，整体呈现圣洁的白色调，无数高耸的尖塔直插云霄，被誉为‘离天空最近的城市’。",
  "districts": [
    {
      "district_name": "王宫区 (Palace District)",
      "description": "位于城市的最中心，也是地势最高处。艾尔多拉王宫‘云顶天宫’坐落于此，被强大的魔法结界和精锐的王家卫队守护着。此区域不对公众开放，是王室成员与最高政要的专属区域。",
      "points_of_interest": [
        {
          "poi_name": "云顶天宫 (Cloud-Top Palace)",
          "description": "艾尔多拉王室的居所与权力中心，传说其基座直接与浮空岛的核心相连。内部设有议政厅、皇家图书馆、王室寝宫以及历代国王的陵寝。"
        },
        {
          "poi_name": "星见之塔 (Stargazer's Spire)",
          "description": "王宫区最高的建筑，由王室首席法师掌管。用于观测星象、监控云海的以太流向以及维系覆盖全城的防御结界。"
        }
      ]
    },
    {
      "district_name": "贵族区 (Noble District)",
      "description": "环绕着王宫区的优雅区域，是各大贵族家族宅邸的所在地。这里的街道宽阔，环境清幽，遍布着精致的花园和私人会所。",
      "points_of_interest": [
        {
          "poi_name": "公爵大道 (Duke's Promenade)",
          "description": "贵族区的主要街道，两旁是各大公爵和侯爵家族的宏伟府邸，安保森严。"
        },
        {
          "poi_name": "皇家歌剧院 (Royal Opera House)",
          "description": "由王室资助建造的豪华剧院，是贵族们享受高雅艺术和进行社交活动的重要场所。"
        }
      ]
    },
    {
      "district_name": "中央商业区 (Central Commercial District)",
      "description": "圣特兰最繁华的区域，汇集了来自世界各地的商品和商人。这里有昂贵的精品店、大型商会、异国风味的餐厅以及云海世界最大的拍卖行。",
      "points_of_interest": [
        {
          "poi_name": "黄金广场 (Golden Plaza)",
          "description": "商业区的中心广场，广场中央矗立着一座巨大的财富女神喷泉雕像。四周环绕着圣特兰最大的几家银行和商会总部。"
        },
        {
          "poi_name": "天穹拍卖行 (Sky-Dome Auction House)",
          "description": "艾尔多拉世界最富盛名的拍卖行，从珍稀的魔法材料、古代遗物到被捕获的奇特魔物，任何有价值的东西都可能出现在这里。"
        }
      ]
    },
    {
      "district_name": "冒险者与工匠区 (Adventurer & Artisan District)",
      "description": "冒险者协会总部、各大工匠作坊和中低阶层市民的居住区。相比于贵族区和商业区的光鲜亮丽，这里充满了活力与喧嚣，空气中弥漫着麦酒、汗水和金属锻造的气味。",
      "points_of_interest": [
        {
          "poi_name": "冒险者协会总部 (Adventurer's Guild Headquarters)",
          "description": "一栋宏伟的堡垒式建筑，是所有冒险者的圣地。这里不仅发布着最高难度的S级任务，还拥有最顶尖的训练设施和情报网络。"
        },
        {
          "poi_name": "蒸汽核心工坊 (Steam-Core Workshops)",
          "description": "矮人与侏儒工匠的聚集地，负责以太方舟的建造与维修，以及各种蒸汽动力机械的研发。巨大的烟囱终日冒着白烟。"
        },
        {
          "poi_name": "无眠酒馆街 (Sleepless Tavern Street)",
          "description": "一条遍布酒馆、旅店和娱乐场所的街道，是冒险者们任务归来后放松消遣的地方，昼夜不息。"
        }
      ]
    },
    {
      "district_name": "港口区 (Port District)",
      "description": "位于圣特兰边缘，地势最低处的区域。无数巨大的船坞延伸至云海之中，各种型号的以太方舟在这里起降。这里鱼龙混杂，是货物装卸、水手招募和信息流转的地方。",
      "points_of_interest": [
        {
          "poi_name": "中央大港 (Grand Central Port)",
          "description": "官方运营的最大港口，主要用于大型商船、客运飞艇和军用舰船的停泊。"
        },
        {
          "poi_name": "走私者码头 (Smuggler's Wharf)",
          "description": "一个半公开的秘密码头，由灰色势力控制。许多无法通过正规渠道交易的货物和情报在此流通。"
        }
      ]
    },
    {
      "district_name": "学院区 (Academy District)",
      "description": "知识与魔法的殿堂。皇家魔法学院和综合文理学院坐落于此，培养着王国未来的法师、学者和官员。区域内学术氛围浓厚，环境宁静。",
      "points_of_interest": [
        {
          "poi_name": "皇家魔法学院 (Royal Academy of Magic)",
          "description": "艾尔多拉最顶尖的魔法教育机构，只招收有魔法天赋的学生。学院本身就是一座巨大的魔法要塞。"
        },
        {
          "poi_name": "大图书馆 (The Grand Library)",
          "description": "收藏着自‘大崩裂’时代以来海量书籍和文献的巨型图书馆，对所有市民开放，但进入禁书区需要特殊许可。"
        }
      ]
    }
  ]
}

