entries.content:
{
  "location_name": "艾尔多拉王宫 - 云顶天宫 (Aeldoran Royal Palace - Cloud-Top Palace)",
  "location_type": "核心政治建筑/王族居所",
  "island": "中央圣殿岛 (Central Sanctuary Isle)",
  "geographical_position": "位于王都圣特兰正中心，也是整座浮空岛的最高点。宫殿建立在一块自岛屿主体向上延伸出的、经过魔法强化的巨大岩盘之上，四周被数千米深的云峡环绕，仅通过一座名为‘虹光之桥’的魔法桥梁与贵族区相连。",
  "description": "艾尔多拉王国的权力中枢与王室世代的居所。整座宫殿由圣洁的‘光洁岩’与珍贵的‘星辰水晶’筑成，在阳光下熠熠生辉，宛如云海之上永不坠落的星辰。宫殿常年被强大的远古结界‘苍穹之守护’所笼罩，能够抵御S级以下的任何物理与魔法攻击。传说其地基深处，与维系整个‘中央圣殿岛’悬浮的以太核心直接相连。",
  "internal_layout": [
    {
      "area_name": "外廷 (Outer Court)",
      "description": "用于举行大型典礼、接见使臣和高级官员议事的区域。",
      "points_of_interest": [
        {
          "poi_name": "御座厅 (Throne Room)",
          "description": "国王的御座所在地，是王国最高权力的象征。巨大的穹顶绘有创世神话的壁画，地面由一整块打磨光滑的黑曜石铺就，能够倒映出穹顶的星辰图像。"
        },
        {
          "poi_name": "英雄长廊 (Hall of Heroes)",
          "description": "连接御座厅与外廷大门的长廊。两侧墙壁上悬挂着历代为王国做出杰出贡献的英雄与将领的肖像，以及他们使用过的武器或物品。"
        },
        {
          "poi_name": "虹光之桥 (Rainbow Bridge)",
          "description": "连接王宫与贵族区的唯一通道。桥身由纯粹的光能构成，颜色会随着时间缓慢变化。只有王室成员、受邀的贵族或持有特别通行证的人才能通过。"
        }
      ]
    },
    {
      "area_name": "内廷 (Inner Court)",
      "description": "王室成员的日常生活区域，守卫森严，禁止外人入内。",
      "points_of_interest": [
        {
          "poi_name": "公主寝宫 - 蔷薇园 (Princess's Chambers - Rose Garden)",
          "description": "莉莉安娜公主的居所。位于内廷东侧，拥有一座独立的空中花园，花园里种满了来自世界各地的珍稀蔷薇品种。建筑风格优雅而精致。"
        },
        {
          "poi_name": "国王寝宫 - 静思堂 (King's Quarters - Hall of Contemplation)",
          "description": "现任国王的寝室与书房，风格庄重典雅。据传内部设有密道，可以直达王宫的各个重要区域。"
        },
        {
          "poi_name": "皇家图书馆 - 真理之卷 (Royal Library - Scrolls of Truth)",
          "description": "收藏着大量不对外公开的古籍、魔法书和历史文献，包括关于‘大崩裂’的原始记录。由王室最信赖的学者管理。"
        },
        {
          "poi_name": "空中花园 - 伊甸 (Hanging Gardens - Eden)",
          "description": "位于内廷顶层的大型花园，通过精密的魔法维持着四季如春的气候，是王室成员休憩和举办小型宴会的场所。"
        }
      ]
    },
    {
      "area_name": "禁区 (Forbidden Zone)",
      "description": "王宫内最为机密的区域，由王家直属的魔法师团和古代魔像共同守护。",
      "points_of_interest": [
        {
          "poi_name": "星见之塔 (Stargazer's Spire)",
          "description": "位于王宫最高处的独立高塔。不仅是观测星象的场所，更是‘苍穹之守护’结界的能量核心所在地。只有国王和首席宫廷法师才能进入。"
        },
        {
          "poi_name": "历代君王之墓 (Tomb of the Kings)",
          "description": "位于王宫地下的巨大陵寝，安葬着艾尔多拉王国的历代君主。传说这里隐藏着王室最大的秘密。"
        },
        {
          "poi_name": "以太核心室 (Aether Core Chamber)",
          "description": "王宫最深处，直接连通浮空岛的动力源。这里的以太浓度极高，未经特殊防护进入的人会被瞬间能量化。"
        }
      ]
    }
  ],
  "important_personnel": [
    {
      "npc_name": "国王 - 奥古斯都·冯·艾尔多拉三世 (King Augustus von Aeldora III)",
      "npc_tier": "配角NPC (Supporting NPC)",
      "role": "艾尔多拉王国现任君主",
      "basic_info": {
        "age": 58,
        "appearance": "金发碧眼，面容威严，岁月在他脸上刻下了深刻的纹路，但眼神依旧锐利。常年穿着华贵的王室礼服。"
      },
      "personality_script": "威严/睿智/多疑。作为一国之君，他将王国的稳定与传承视为最高利益。对冒险者协会既利用又警惕，对虚空教团深恶痛绝。由于唯一的继承人是女儿，他正在为公主的未来，以及王国的未来而深感焦虑。",
      "dialogue_sample": [
        "王国的荣耀，高于一切。",
        "冒险者是把双刃剑，必须小心使用。",
        "莉莉安娜，你必须学会如何成为一个合格的继承人。"
      ]
    },
    {
      "npc_name": "公主 - 莉莉安娜·冯·艾尔多拉 (Princess Liliana von Aeldora)",
      "npc_tier": "主要NPC (Main NPC / Companion)",
      "role": "王位第一顺位继承人/治愈魔法的天才",
      "basic_info": {
        "age": 17,
        "appearance": "继承了王室的灿烂金发与碧绿眼眸，肌肤白皙，容貌精致得如同人偶。气质纯洁而高贵，同时又带有一丝不谙世事的天然。"
      },
